def runlen(g,v,minn,maxn):
    g=np.array(g); c=0
    H,W=g.shape
    # horizontal runs >= minn, <= maxn
    for i in range(H):
        run=0
        for j in range(W):
            if g[i,j]==v: run+=1
            else:
                if minn<=run<=maxn: c+=1
                run=0
        if minn<=run<=maxn: c+=1
    # vertical similar
    for j in range(W):
        run=0
        for i in range(H):
            if g[i,j]==v: run+=1
            else:
                if minn<=run<=maxn: c+=1
                run=0
        if minn<=run<=maxn: c+=1
    return c
